/**
 * The text of a `DATA_FORMAT.md` (#692): the format of the data files of one folder, for the agent
 * and the person. Eva writes the whole file from the approved widgets of the folder, so it holds
 * no text of the person. The person's notes go in the `AGENTS.md` or the `README.md` of the folder.
 */
import { mergeFormats, type MergedField } from "./data-formats.ts";

export const dataFormatFileName = "DATA_FORMAT.md";

export const dataFormatFirstLine =
  "Generated by Eva. Do not edit. Write your notes in the AGENTS.md or the README.md of this folder.";

/** One widget input with a schema in the folder. */
export interface DataFormatUse {
  readonly widget: string;
  readonly name: string;
  readonly access: "read" | "write";
  /** The `files` pattern of a folder input, the file name of a file input, or null for every file. */
  readonly files: string | null;
  /** True for a file input: the pattern is one file of this folder, not of its subfolders. */
  readonly single: boolean;
  readonly schema: unknown;
}

/** A cell of a table keeps to one line, so the author's text cannot break the table. */
const maxCell = 300;

export function dataFormatText(folder: string, uses: readonly DataFormatUse[]): string {
  const { fields } = mergeFormats(uses.map(({ widget, name, schema }) => ({ widget, name, schema })));
  const widgets = uses.map((use) => `- ${use.name} (\`${use.widget}\`) ${verb(use)} ${place(use)}.`);
  const rows = fields.map((field) =>
    [
      `\`${field.path}\``,
      field.types?.join(" or ") ?? "any",
      allowed(field),
      field.requiredBy.join(", "),
      field.usedBy.join(", "),
      field.descriptions.length === 1
        ? (field.descriptions[0]?.text ?? "")
        : field.descriptions.map((each) => `${each.name}: ${each.text}`).join(" "),
    ].map(cell),
  );
  return [
    dataFormatFirstLine,
    "",
    `# The data format of \`${folder}\``,
    "",
    "Eva writes this file from the widgets that use this folder. Follow it when you write a data file here.",
    "",
    "## Widgets",
    "",
    ...widgets,
    "",
    "## How to write a file",
    "",
    "- Each data file is one JSON or YAML object.",
    "- Write every required field. The column Required by names the widgets that need it.",
    "- Keep each field that you do not know. Another widget or the person can use it.",
    "- Each widget reads only its own fields. Two fields can hold the same value, such as a `location` of one widget and a `place` of another. Fill each of them.",
    "",
    "## Fields",
    "",
    "A field such as `items[].date` is the field `date` of each item of the list `items`.",
    "",
    "| Field | Type | Allowed values | Required by | Used by | Description |",
    "| --- | --- | --- | --- | --- | --- |",
    ...rows.map((row) => `| ${row.join(" | ")} |`),
    "",
    "## Example",
    "",
    "```json",
    JSON.stringify(exampleOf(fields), null, 2),
    "```",
    "",
  ].join("\n");
}

function verb(use: DataFormatUse): string {
  return use.access === "write" ? "reads and writes" : "reads";
}

function place(use: DataFormatUse): string {
  if (use.single) return `the file \`${use.files ?? ""}\``;
  const files = use.files === null ? "every file" : `the files \`${use.files}\``;
  return `${files} in this folder and its subfolders`;
}

function allowed(field: MergedField): string {
  if (field.values !== null) return field.values.map((value) => JSON.stringify(value)).join(", ");
  return field.format === null ? "any" : `format ${field.format}`;
}

function cell(text: string): string {
  const line = text.replace(/\s+/g, " ").trim().replaceAll("|", "\\|");
  return line.length > maxCell ? `${line.slice(0, maxCell - 1)}…` : line;
}

/** One example file with a value for each field. */
export function exampleOf(fields: readonly MergedField[]): unknown {
  const byPath = new Map(fields.map((field) => [field.path, field]));
  const childrenOf = (prefix: string): MergedField[] =>
    fields.filter((field) => {
      const rest =
        prefix === "" ? field.path : field.path.startsWith(`${prefix}.`) ? field.path.slice(prefix.length + 1) : null;
      return rest !== null && rest !== "" && !rest.includes(".") && !rest.includes("[]");
    });
  const objectAt = (prefix: string): Record<string, unknown> => {
    const object: Record<string, unknown> = {};
    for (const field of childrenOf(prefix)) {
      const key = field.path.slice(prefix === "" ? 0 : prefix.length + 1);
      Object.defineProperty(object, key, {
        value: valueAt(field),
        enumerable: true,
        writable: true,
        configurable: true,
      });
    }
    return object;
  };
  const valueAt = (field: MergedField): unknown => {
    const item = byPath.get(`${field.path}[]`);
    if (item !== undefined) return [valueAt(item)];
    if (field.types?.includes("array") === true) return [];
    if (childrenOf(field.path).length > 0 || field.types?.includes("object") === true) return objectAt(field.path);
    return leafValue(field);
  };
  return objectAt("");
}

function leafValue(field: MergedField): unknown {
  if (field.values !== null && field.values.length > 0) return field.values[0];
  if (field.format === "date") return "2026-01-01";
  if (field.format === "date-time") return "2026-01-01T09:30:00Z";
  if (field.format === "time") return "09:30:00";
  if (field.format === "email") return "name@example.com";
  if (field.format === "uri") return "https://example.com";
  // A real value over null, so an agent that copies the example writes data.
  const type = field.types?.find((each) => each !== "null") ?? field.types?.[0] ?? "string";
  if (type === "number" || type === "integer") return 1;
  if (type === "boolean") return true;
  if (type === "null") return null;
  return "text";
}
